import{_ as e,a}from"./chunks/dq-2.DyErWHxW.js";import{_ as o,o as i,c as r,a5 as n}from"./chunks/framework.DGp912Ge.js";const f=JSON.parse('{"title":"DQ Calibration","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/troubleshooting/dq-calibration.md","filePath":"manual/troubleshooting/dq-calibration.md","lastUpdated":1785806767000}'),l={name:"manual/troubleshooting/dq-calibration.md"};function s(d,t,h,c,b,g){return i(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="dq-calibration" tabindex="-1">DQ Calibration <a class="header-anchor" href="#dq-calibration" aria-label="Permalink to &quot;DQ Calibration&quot;">​</a></h1><p>Use <strong>DQ ALIGN</strong> to reset the encoder zero reference after replacing a joint board, joint module, or whenever the encoder zero has shifted.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">Caution</p><p>The target joint will move slightly when DQ ALIGN is executed. Keep people and obstacles clear of the robot, and ensure the robot is sitting stably on the floor before proceeding.</p></div></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>RBQ GUI (PC application) connected to the robot</li><li>Robot in a sitting pose, with the joint to be calibrated able to move slightly</li></ul><hr><figure style="margin-top:1rem;text-align:center;"><img src="'+e+'" alt="" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;"></figcaption></figure><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procedure&quot;">​</a></h2><h3 id="_1-turn-on-leg-power" tabindex="-1">1. Turn on LEG power <a class="header-anchor" href="#_1-turn-on-leg-power" aria-label="Permalink to &quot;1. Turn on LEG power&quot;">​</a></h3><p>Select the <strong>Power</strong> tab at the top and turn <strong>LEG power ON</strong>.</p><h3 id="_2-open-the-joint-table" tabindex="-1">2. Open the joint table <a class="header-anchor" href="#_2-open-the-joint-table" aria-label="Permalink to &quot;2. Open the joint table&quot;">​</a></h3><p>Click <strong>View → Show Bottom Bar</strong> in the top menu bar. The joint table will appear at the bottom of the screen.</p><h3 id="_3-go-to-the-joint-tab" tabindex="-1">3. Go to the Joint tab <a class="header-anchor" href="#_3-go-to-the-joint-tab" aria-label="Permalink to &quot;3. Go to the Joint tab&quot;">​</a></h3><p>Select the <strong>Joint</strong> tab at the top.</p><h3 id="_4-run-dq-align" tabindex="-1">4. Run DQ ALIGN <a class="header-anchor" href="#_4-run-dq-align" aria-label="Permalink to &quot;4. Run DQ ALIGN&quot;">​</a></h3><ol><li>Select the joint to calibrate in <strong>Selected joint</strong> or the <strong>Joint table</strong>.</li><li>Click the <strong>DQ ALIGN</strong> button.</li><li>The joint will <strong>move slightly</strong> as it finds the encoder zero.</li><li>Click <strong>BOARD RESET</strong> to reset the board.</li></ol><h3 id="_5-repeat-for-remaining-joints" tabindex="-1">5. Repeat for remaining joints <a class="header-anchor" href="#_5-repeat-for-remaining-joints" aria-label="Permalink to &quot;5. Repeat for remaining joints&quot;">​</a></h3><p>Repeat <strong>step 4</strong> for every joint that requires calibration.</p><hr><figure style="margin-top:1rem;text-align:center;"><img src="'+a+'" alt="" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;"></figcaption></figure><h2 id="confirm-calibration" tabindex="-1">Confirm calibration <a class="header-anchor" href="#confirm-calibration" aria-label="Permalink to &quot;Confirm calibration&quot;">​</a></h2><p>When the <strong>Angle</strong> value in the joint table shows a normal range, calibration is complete. The robot can then proceed through the normal <strong>Auto Start Robot</strong> sequence.</p><h2 id="when-is-this-needed" tabindex="-1">When is this needed? <a class="header-anchor" href="#when-is-this-needed" aria-label="Permalink to &quot;When is this needed?&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Situation</th><th style="text-align:left;">DQ Calibration required</th></tr></thead><tbody><tr><td style="text-align:left;">After replacing a joint board</td><td style="text-align:left;">Yes</td></tr><tr><td style="text-align:left;">After replacing a full joint module</td><td style="text-align:left;">Yes</td></tr><tr><td style="text-align:left;">Find Home fails repeatedly</td><td style="text-align:left;">Possibly</td></tr><tr><td style="text-align:left;">A joint shows an abnormal angle after initialization</td><td style="text-align:left;">Possibly</td></tr><tr><td style="text-align:left;">Normal operation</td><td style="text-align:left;">Not needed</td></tr></tbody></table>',24)])])}const m=o(l,[["render",s]]);export{f as __pageData,m as default};
